import { describe, it, expect, vi } from 'vitest';
import { SlackAuthError, verifySlackAuth, type SlackAuthVerifier } from '../verifyAuth.js';

function makeVerifier(impl: SlackAuthVerifier['test']): SlackAuthVerifier {
  return { test: impl };
}

describe('verifySlackAuth', () => {
  it('resolves when auth.test succeeds', async () => {
    const verifier = makeVerifier(async () => ({ ok: true, user_id: 'U123', team_id: 'T1' }));
    await expect(verifySlackAuth(verifier)).resolves.toBeUndefined();
  });

  it('throws SlackAuthError(invalid_auth) with actionable hint when token rejected', async () => {
    const slackErr: Error & { code?: string; data?: { error?: string } } = Object.assign(
      new Error('An API error occurred: invalid_auth'),
      { code: 'slack_webapi_platform_error', data: { ok: false, error: 'invalid_auth' } },
    );
    const verifier = makeVerifier(async () => {
      throw slackErr;
    });

    await expect(verifySlackAuth(verifier)).rejects.toMatchObject({
      name: 'SlackAuthError',
      kind: 'invalid_auth',
      slackErrorCode: 'invalid_auth',
    });

    try {
      await verifySlackAuth(verifier);
      expect.fail('should have thrown');
    } catch (err) {
      expect(err).toBeInstanceOf(SlackAuthError);
      expect((err as SlackAuthError).message).toMatch(/SLACK_BOT_TOKEN/);
      expect((err as SlackAuthError).message).toMatch(/xoxb-/);
    }
  });

  it('throws SlackAuthError(other) for non-invalid_auth slack errors', async () => {
    const slackErr: Error & { data?: { error?: string } } = Object.assign(
      new Error('An API error occurred: ratelimited'),
      { data: { ok: false, error: 'ratelimited' } },
    );
    const verifier = makeVerifier(async () => {
      throw slackErr;
    });

    await expect(verifySlackAuth(verifier)).rejects.toMatchObject({
      name: 'SlackAuthError',
      kind: 'other',
      slackErrorCode: 'ratelimited',
    });
  });

  it('throws SlackAuthError(other) when error lacks slack-shaped data', async () => {
    const verifier = makeVerifier(async () => {
      throw new Error('socket hang up');
    });

    await expect(verifySlackAuth(verifier)).rejects.toMatchObject({
      name: 'SlackAuthError',
      kind: 'other',
    });
  });

  it('passes through the verifier exactly once', async () => {
    const test = vi.fn(async () => ({ ok: true }));
    await verifySlackAuth({ test });
    expect(test).toHaveBeenCalledTimes(1);
  });
});

import { describe, expect, it } from 'vitest';
import { DEFAULT_TENANT_CONFIG } from '../../config/tenantConfig.js';
import {
  buildConversationSearchDescription,
  buildLeaveChannelDescription,
  buildLogDecisionDescription,
  buildRespondDirectedAtMeDescription,
  buildRespondToolDescription,
} from '../toolDescriptions.js';

describe('MCP tool descriptions', () => {
  const tenant = {
    ...DEFAULT_TENANT_CONFIG,
    orgName: 'Acme',
    botName: 'Scout',
    botAliases: ['scout', 'helper'],
    effectiveAliases: ['Scout', 'helper'],
    decisionLogChannel: 'team-decisions',
  };

  it('builds respond descriptions from tenant bot name and aliases', () => {
    const description = buildRespondDirectedAtMeDescription(tenant, { linear: true });

    expect(description).toContain('@Scout');
    expect(description).toContain('Scout/helper');
    expect(description).toContain('"thanks scout"');
    expect(description).not.toContain('@scribble');
    expect(description).not.toContain('Scribble/scrib');
  });

  it('does not advertise Linear in respond guidance when Linear is disabled', () => {
    const description = buildRespondDirectedAtMeDescription(tenant, { linear: false });

    expect(description).toContain('wiki and other configured tools');
    expect(description).not.toContain('wiki, Linear, etc.');
  });

  it('keeps the mandatory respond tool description tenant-neutral', () => {
    expect(buildRespondToolDescription()).toBe(
      'You MUST call this tool for EVERY message. This is the only way to send visible responses to Slack.'
    );
  });

  it('builds log_decision description from the configured decision-log channel', () => {
    expect(buildLogDecisionDescription(tenant)).toBe(
      'Log a business decision to #team-decisions with a link back to the source message'
    );
  });

  it('does not prefix Slack channel IDs in log_decision descriptions', () => {
    expect(buildLogDecisionDescription({
      ...tenant,
      decisionLogChannel: 'C0A93A7H820',
    })).toBe('Log a business decision to C0A93A7H820 with a link back to the source message');
  });

  it('builds leave_channel wording without claiming an enforced privacy boundary', () => {
    const description = buildLeaveChannelDescription(tenant);

    expect(description).toContain('Request that Scout leave a Slack channel');
    expect(description).toContain('operator must remove the app or implement leave handling');
    expect(description).not.toContain('stop monitoring');
    expect(description).not.toContain('privacy boundary');
  });

  it('describes conversation_search global logged-channel behavior and citation expectations', () => {
    const description = buildConversationSearchDescription();

    expect(description).toContain('Search logged Slack conversations');
    expect(description).toContain('If `channel_id` is omitted');
    expect(description).toContain('all logged channels');
    expect(description).toContain('clear relevance');
    expect(description).toContain('attribution');
    expect(description).toContain('privacy judgment');
  });
});

import { describe, it, expect } from 'vitest';
import { normalizeConversationSearchArgs } from '../conversationSearchArgs.js';

describe('normalizeConversationSearchArgs', () => {
  it('returns null for empty query', () => {
    expect(normalizeConversationSearchArgs({ query: '' })).toBeNull();
  });

  it('returns null for whitespace-only query', () => {
    expect(normalizeConversationSearchArgs({ query: '   \n' })).toBeNull();
  });

  it('returns null for malformed channel_id', () => {
    expect(normalizeConversationSearchArgs({
      query: 'hi',
      channel_id: '../wiki',
    })).toBeNull();
  });

  it('returns null for channel_id without a Slack channel prefix', () => {
    expect(normalizeConversationSearchArgs({
      query: 'hi',
      channel_id: '10A93A7H820',
    })).toBeNull();
  });

  it('returns null for overlong channel_id', () => {
    expect(normalizeConversationSearchArgs({
      query: 'hi',
      channel_id: `C${'A'.repeat(32)}`,
    })).toBeNull();
  });

  it('clamps limit to 50', () => {
    const result = normalizeConversationSearchArgs({ query: 'hi', limit: 1000 });
    expect(result).not.toBeNull();
    expect(result!.limit).toBe(50);
  });

  it('clamps limit lower bound to 1', () => {
    expect(normalizeConversationSearchArgs({ query: 'hi', limit: 0 })!.limit).toBe(1);
    expect(normalizeConversationSearchArgs({ query: 'hi', limit: -5 })!.limit).toBe(1);
  });

  it('returns null for non-finite limit', () => {
    expect(normalizeConversationSearchArgs({ query: 'hi', limit: Number.NaN })).toBeNull();
    expect(normalizeConversationSearchArgs({ query: 'hi', limit: Number.POSITIVE_INFINITY })).toBeNull();
  });

  it('truncates fractional limit', () => {
    const result = normalizeConversationSearchArgs({ query: 'hi', limit: 2.9 });
    expect(result).not.toBeNull();
    expect(result!.limit).toBe(2);
  });

  it('clamps context to 5', () => {
    const result = normalizeConversationSearchArgs({ query: 'hi', context: 100 });
    expect(result).not.toBeNull();
    expect(result!.context).toBe(5);
  });

  it('clamps context lower bound to 0', () => {
    const result = normalizeConversationSearchArgs({ query: 'hi', context: -1 });
    expect(result).not.toBeNull();
    expect(result!.context).toBe(0);
  });

  it('returns null for non-finite context', () => {
    expect(normalizeConversationSearchArgs({ query: 'hi', context: Number.NaN })).toBeNull();
    expect(normalizeConversationSearchArgs({ query: 'hi', context: Number.NEGATIVE_INFINITY })).toBeNull();
  });

  it('truncates fractional context', () => {
    const result = normalizeConversationSearchArgs({ query: 'hi', context: 2.9 });
    expect(result).not.toBeNull();
    expect(result!.context).toBe(2);
  });

  it('passes through valid args unchanged', () => {
    const result = normalizeConversationSearchArgs({
      query: 'hi',
      channel_id: 'C0A93A7H820',
      date: '2026-05-01',
      limit: 20,
      context: 3,
    });
    expect(result).toEqual({
      query: 'hi',
      channel_id: 'C0A93A7H820',
      date: '2026-05-01',
      limit: 20,
      context: 3,
    });
  });

  it('omitted channel_id is allowed (global search)', () => {
    const result = normalizeConversationSearchArgs({ query: 'hi' });
    expect(result).not.toBeNull();
    expect(result!.channel_id).toBeUndefined();
  });
});

