import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { EventEmitter } from 'eventemitter3';
import { ConnectionMonitor } from '../connectionMonitor.js';

describe('ConnectionMonitor', () => {
  let emitter: EventEmitter;
  let onUnrecoverable: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    vi.useFakeTimers();
    emitter = new EventEmitter();
    onUnrecoverable = vi.fn();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  function createMonitor(opts: { disconnectGracePeriodMs?: number } = {}) {
    return new ConnectionMonitor({
      socketModeClient: emitter,
      onUnrecoverable,
      disconnectGracePeriodMs: opts.disconnectGracePeriodMs ?? 5 * 60 * 1000,
    });
  }

  describe('lifecycle', () => {
    it('starts in disconnected state', () => {
      const monitor = createMonitor();
      expect(monitor.isConnected).toBe(false);
    });

    it('tracks connected state on "connected" event', () => {
      const monitor = createMonitor();
      emitter.emit('connected');
      expect(monitor.isConnected).toBe(true);
    });

    it('tracks disconnected state on "disconnected" event', () => {
      const monitor = createMonitor();
      emitter.emit('connected');
      emitter.emit('disconnected');
      expect(monitor.isConnected).toBe(false);
    });

    it('tracks disconnected state on "close" event', () => {
      const monitor = createMonitor();
      emitter.emit('connected');
      emitter.emit('close');
      expect(monitor.isConnected).toBe(false);
    });

    it('tracks reconnecting as disconnected', () => {
      const monitor = createMonitor();
      emitter.emit('connected');
      emitter.emit('reconnecting');
      expect(monitor.isConnected).toBe(false);
    });
  });

  describe('grace period', () => {
    it('does not call onUnrecoverable during grace period', () => {
      const monitor = createMonitor({ disconnectGracePeriodMs: 60_000 });
      emitter.emit('connected');
      emitter.emit('disconnected');

      vi.advanceTimersByTime(59_999);
      expect(onUnrecoverable).not.toHaveBeenCalled();
    });

    it('calls onUnrecoverable after grace period expires', () => {
      const monitor = createMonitor({ disconnectGracePeriodMs: 60_000 });
      emitter.emit('connected');
      emitter.emit('disconnected');

      vi.advanceTimersByTime(60_000);
      expect(onUnrecoverable).toHaveBeenCalledOnce();
    });

    it('cancels timer if reconnected within grace period', () => {
      const monitor = createMonitor({ disconnectGracePeriodMs: 60_000 });
      emitter.emit('connected');
      emitter.emit('disconnected');

      vi.advanceTimersByTime(30_000);
      emitter.emit('connected');

      vi.advanceTimersByTime(60_000);
      expect(onUnrecoverable).not.toHaveBeenCalled();
    });

    it('resets timer on repeated disconnects', () => {
      const monitor = createMonitor({ disconnectGracePeriodMs: 60_000 });
      emitter.emit('connected');
      emitter.emit('disconnected');

      vi.advanceTimersByTime(30_000);
      // Another disconnect event (e.g. reconnect attempt failed)
      emitter.emit('disconnected');

      // 30s from first disconnect, but timer was reset — should not fire yet
      vi.advanceTimersByTime(30_000);
      expect(onUnrecoverable).not.toHaveBeenCalled();

      // Now 60s from the *second* disconnect
      vi.advanceTimersByTime(30_000);
      expect(onUnrecoverable).toHaveBeenCalledOnce();
    });

    it('does not start grace period timer if never connected', () => {
      const monitor = createMonitor({ disconnectGracePeriodMs: 60_000 });
      // disconnected event without ever connecting — initial state, don't trigger
      emitter.emit('disconnected');

      vi.advanceTimersByTime(120_000);
      expect(onUnrecoverable).not.toHaveBeenCalled();
    });
  });

  describe('cleanup', () => {
    it('removes listeners and clears timers on destroy', () => {
      const monitor = createMonitor({ disconnectGracePeriodMs: 60_000 });
      emitter.emit('connected');
      emitter.emit('disconnected');

      monitor.destroy();

      // Timer should be cleared
      vi.advanceTimersByTime(120_000);
      expect(onUnrecoverable).not.toHaveBeenCalled();

      // Events should be unsubscribed
      expect(emitter.listenerCount('connected')).toBe(0);
      expect(emitter.listenerCount('disconnected')).toBe(0);
    });
  });

  describe('error events', () => {
    it('does not crash on error events', () => {
      const monitor = createMonitor();
      emitter.emit('connected');
      expect(() => emitter.emit('error', new Error('test'))).not.toThrow();
    });
  });
});

// Pre-flight Slack auth check.
//
// Bolt's App.start() also calls auth.test under the hood, but failures escape
// as raw uncaught exceptions before our main() can intercept them. Calling
// auth.test ourselves first lets us emit a single actionable error line and
// exit cleanly, instead of a Node stack trace.

/** Minimal slice of WebClient.auth used by verifySlackAuth (dependency injection point). */
export interface SlackAuthVerifier {
  test(): Promise<unknown>;
}

export type SlackAuthErrorKind = 'invalid_auth' | 'other';

export class SlackAuthError extends Error {
  readonly kind: SlackAuthErrorKind;
  readonly slackErrorCode?: string;

  constructor(message: string, kind: SlackAuthErrorKind, slackErrorCode?: string) {
    super(message);
    this.name = 'SlackAuthError';
    this.kind = kind;
    this.slackErrorCode = slackErrorCode;
  }
}

function readSlackErrorCode(err: unknown): string | undefined {
  if (typeof err !== 'object' || err === null) return undefined;
  const data = (err as { data?: unknown }).data;
  if (typeof data === 'object' && data !== null) {
    const code = (data as { error?: unknown }).error;
    if (typeof code === 'string') return code;
  }
  return undefined;
}

export async function verifySlackAuth(verifier: SlackAuthVerifier): Promise<void> {
  try {
    await verifier.test();
  } catch (err) {
    const slackErrorCode = readSlackErrorCode(err);

    if (slackErrorCode === 'invalid_auth') {
      throw new SlackAuthError(
        'SLACK_BOT_TOKEN was rejected by Slack (invalid_auth). Verify it starts with xoxb-, belongs to the installed Slack app, and has not been revoked. See README "Slack App Setup".',
        'invalid_auth',
        slackErrorCode,
      );
    }

    const detail = slackErrorCode ?? (err instanceof Error ? err.message : String(err));
    throw new SlackAuthError(
      `Slack auth.test failed: ${detail}`,
      'other',
      slackErrorCode,
    );
  }
}

import { isValidSlackChannelId } from '../utils/slackIds.js';

const MAX_LIMIT = 50;
const MAX_CONTEXT = 5;

export interface NormalizedConversationSearchArgs {
  query: string;
  channel_id?: string;
  date?: string;
  limit?: number;
  context?: number;
}

export function normalizeConversationSearchArgs(args: {
  query: string;
  channel_id?: string;
  date?: string;
  limit?: number;
  context?: number;
}): NormalizedConversationSearchArgs | null {
  if (typeof args.query !== 'string' || args.query.trim().length === 0) return null;
  if (args.channel_id !== undefined && !isValidSlackChannelId(args.channel_id)) return null;

  const limit = normalizeNumber(args.limit, 1, MAX_LIMIT);
  if (limit === null) return null;

  const context = normalizeNumber(args.context, 0, MAX_CONTEXT);
  if (context === null) return null;

  return {
    query: args.query,
    channel_id: args.channel_id,
    date: args.date,
    limit,
    context,
  };
}

function normalizeNumber(value: number | undefined, min: number, max: number): number | undefined | null {
  if (value === undefined) return undefined;
  if (!Number.isFinite(value)) return null;
  const integer = Math.trunc(value);
  return Math.max(min, Math.min(integer, max));
}

